      "interpretation": "Assistant must deny user requests that are against policy or explicitly state if a request cannot be handled within its scope.",
      "modality": "REQUIRE"
    },
    {
      "policy_source_id": "q3",
      "interpretation": "Assistant must transfer the user to a human agent only if the request cannot be handled within its scope, using the tool `transfer_to_human_agents` and the message 'YOU ARE BEING TRANSFERRED TO A HUMAN AGENT. PLEASE HOLD ON.'",
      "modality": "REQUIRE"
    },
    {
      "policy_source_id": "q3",
      "interpretation": "Assistant must attempt to resolve the issue before transferring the user to a human agent.",
      "modality": "REQUIRE"
