    {
      "policy_source_id": "q2",
      "interpretation": "Assistant must communicate with the user in Russian.",
      "modality": "REQUIRE"
    }
  ],
  "supporting_evidence": [
    {
      "source_id": "h34",
      "actor": "user",
      "role": "user",
      "fact": "User confirmed APN settings (MMSC URL: `http://mms.carrier.com/mms/wapenc`) are unchanged and appear correct."
    },
