      "source_id": "h23",
      "actor": "user",
      "role": "user",
      "fact": "Tool response `can_send_mms` still indicates MMS functionality is unavailable despite network and APN settings being correct."
    },
    {
      "source_id": "q5",
      "actor": "system",
      "role": "policy_span",
      "fact": "Tool `check_wifi_calling_status` and `check_app_permissions` are valid diagnostic tools for troubleshooting MMS issues."
    },
    {
      "source_id": "q3",
